@page "/apply"
@using sv_3c4b90602a3e4025bd8e8c4cb2a792c2.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

<!-- Step Indicator Bar -->
<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < _currentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="alert alert-danger">@_errorMessage</div>
}

<!-- Step 1: Personal Info -->
@if (_currentStep == 0)
{
    <div class="form-section">
        <h2>Personal Information</h2>

        <div class="form-group">
            <label for="fullName">Full Name *</label>
            <input id="fullName" type="text" class="form-control" @bind="_fullName" />
        </div>

        <div class="form-group">
            <label for="email">Email *</label>
            <input id="email" type="email" class="form-control" @bind="_email" />
        </div>

        <div class="form-group">
            <label for="phone">Phone *</label>
            <input id="phone" type="tel" class="form-control" @bind="_phone" />
        </div>

        <div class="form-group">
            <label for="address">Address *</label>
            <input id="address" type="text" class="form-control" @bind="_address" />
        </div>

        <div class="form-buttons">
            <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                @if (_isValidating)
                {
                    <span>Validating...</span>
                }
                else
                {
                    <span>Next</span>
                }
            </button>
        </div>
    </div>
}

<!-- Step 2: Work History -->
@if (_currentStep == 1)
{
    <div class="form-section">
        <h2>Work History</h2>

        @for (int i = 0; i < _workEntries.Count; i++)
        {
            var index = i;
            <div class="work-entry-card">
                <div class="work-entry-header">
                    <h4>Position @(index + 1)</h4>
                    @if (_workEntries.Count > 1)
                    {
                        <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                </div>

                <div class="form-group">
                    <label>Company Name *</label>
                    <input type="text" class="form-control" @bind="_workEntries[index].Company" />
                </div>

                <div class="form-group">
                    <label>Job Title *</label>
                    <input type="text" class="form-control" @bind="_workEntries[index].Title" />
                </div>

                <div class="form-row">
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" class="form-control" @bind="_workEntries[index].StartDate" />
                    </div>

                    <div class="form-group">
                        @if (!_workEntries[index].IsCurrent)
                        {
                            <label>End Date</label>
                            <input type="date" class="form-control" @bind="_workEntries[index].EndDate" />
                        }
                        <div class="form-check">
                            <input type="checkbox" class="form-check-input" id="current-@index" @bind="_workEntries[index].IsCurrent" />
                            <label class="form-check-label" for="current-@index">Currently working here</label>
                        </div>
                    </div>
                </div>

                <div class="form-group">
                    <label>Description</label>
                    <textarea class="form-control" rows="3" @bind="_workEntries[index].Description"></textarea>
                </div>
            </div>
        }

        <button class="btn btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>

        <div class="form-buttons">
            <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
        </div>
    </div>
}

<!-- Step 3: References -->
@if (_currentStep == 2)
{
    <div class="form-section">
        <h2>References</h2>

        @for (int i = 0; i < _references.Count; i++)
        {
            var index = i;
            <div class="reference-card">
